//
//  RubyTextView.swift
//  SwiftMandarin
//
//  Ruby text display for Chinese characters with pinyin annotations
//  Displays pinyin directly above each character/word segment
//

import SwiftUI

/// A word segment with its pinyin displayed above the character
struct RubySegment: Identifiable {
    let id = UUID()
    let text: String
    let pinyin: String
    let partOfSpeech: PartOfSpeech

    /// Translated meaning (fetched asynchronously)
    var translation: String?

    init(from analyzedWord: AnalyzedWord) {
        self.text = analyzedWord.text
        self.pinyin = PinyinConverter.convert(analyzedWord.text)
        self.partOfSpeech = analyzedWord.partOfSpeech
        self.translation = nil
    }

    /// Check if segment is valid for display (has actual content)
    var isValidForDisplay: Bool {
        !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    /// Whether this segment is punctuation (should be displayed inline without ruby annotation)
    var isPunctuation: Bool {
        partOfSpeech.isPunctuation || 
        (!text.contains(where: { $0.isChineseCharacter || $0.isLetter }))
    }
}

/// Interactive ruby text view that displays Chinese characters with pinyin above
/// Tapping on a word/character shows a popup with details
struct RubyTextView: View {
    let chineseText: String
    let englishMeaning: String
    let onWordTap: ((RubySegment) -> Void)?

    @State private var segments: [RubySegment] = []

    init(chineseText: String, englishMeaning: String = "", onWordTap: ((RubySegment) -> Void)? = nil) {
        self.chineseText = chineseText
        self.englishMeaning = englishMeaning
        self.onWordTap = onWordTap
    }

    var body: some View {
        FlowLayout(spacing: 4) {
            ForEach(segments.filter { $0.isValidForDisplay }) { segment in
                if segment.isPunctuation {
                    // Display punctuation inline without ruby annotation
                    PunctuationView(text: segment.text)
                } else {
                    RubyWordView(segment: segment) {
                        onWordTap?(segment)
                    }
                }
            }
        }
        .onAppear {
            updateSegments()
        }
        .onChange(of: chineseText) { _, _ in
            updateSegments()
        }
    }

    private func updateSegments() {
        let analyzed = ChineseTextAnalyzer.shared.segmentWithPartsOfSpeech(chineseText)
        segments = analyzed.map { RubySegment(from: $0) }
    }
}

/// Inline punctuation display (no ruby annotation)
/// Aligns with the baseline of Chinese characters by adding top padding
/// to account for the pinyin space above regular RubyWordViews
struct PunctuationView: View {
    let text: String

    var body: some View {
        VStack(spacing: 2) {
            // Empty space to match pinyin height in RubyWordView
            Text(" ")
                .font(.caption)
                .opacity(0)

            // Punctuation aligned with Chinese characters
            Text(text)
                .font(.title2)
                .fontWeight(.medium)
                .foregroundStyle(.primary)
        }
        .padding(.vertical, 4)
    }
}

/// Individual word with pinyin above the character(s)
struct RubyWordView: View {
    let segment: RubySegment
    let action: () -> Void

    @State private var isHovered: Bool = false

    var body: some View {
        Button(action: action) {
            VStack(spacing: 2) {
                // Pinyin above
                Text(segment.pinyin)
                    .font(.caption)
                    .foregroundStyle(pinyinColor)
                    .lineLimit(1)
                    .minimumScaleFactor(0.7)

                // Chinese character(s) below
                Text(segment.text)
                    .font(.title2)
                    .fontWeight(.medium)
                    .foregroundStyle(.primary)
            }
            .padding(.horizontal, 6)
            .padding(.vertical, 4)
            .background(
                RoundedRectangle(cornerRadius: 6)
                    .fill(isHovered ? Color.accentColor.opacity(0.1) : Color.clear)
            )
            .overlay(
                RoundedRectangle(cornerRadius: 6)
                    .stroke(segment.partOfSpeech.color.opacity(0.3), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
        .onHover { hovering in
            withAnimation(.easeInOut(duration: 0.15)) {
                isHovered = hovering
            }
        }
    }

    /// Color for pinyin based on tone
    private var pinyinColor: Color {
        // Get the first tone mark to determine color
        let pinyin = segment.pinyin.lowercased()

        if pinyin.contains("ā") || pinyin.contains("ē") || pinyin.contains("ī") || pinyin.contains("ō") || pinyin.contains("ū") || pinyin.contains("ǖ") {
            return .red // First tone
        } else if pinyin.contains("á") || pinyin.contains("é") || pinyin.contains("í") || pinyin.contains("ó") || pinyin.contains("ú") || pinyin.contains("ǘ") {
            return .orange // Second tone
        } else if pinyin.contains("ǎ") || pinyin.contains("ě") || pinyin.contains("ǐ") || pinyin.contains("ǒ") || pinyin.contains("ǔ") || pinyin.contains("ǚ") {
            return .green // Third tone
        } else if pinyin.contains("à") || pinyin.contains("è") || pinyin.contains("ì") || pinyin.contains("ò") || pinyin.contains("ù") || pinyin.contains("ǜ") {
            return .blue // Fourth tone
        } else {
            return .secondary // Neutral tone
        }
    }
}

/// Detailed popup view for a selected word
/// Fetches the actual translation of the word using Translation API
/// Always displays: Chinese word, pinyin, and English definition
/// Handles both Chinese and English input words
struct WordDetailPopover: View {
    let segment: RubySegment
    let contextTranslation: String  // Full sentence translation for context
    let onSave: (String) -> Void    // Pass the word definition when saving
    let onCopy: () -> Void
    let onDismiss: () -> Void

    @Environment(SavedTermsStore.self) private var savedTermsStore
    @State private var showCopiedFeedback: Bool = false
    @State private var englishDefinition: String = ""
    @State private var chineseWord: String = ""
    @State private var pinyinText: String = ""
    @State private var isLoadingTranslation: Bool = true
    @State private var translationError: String?

    /// Check if the segment text contains Chinese characters
    private var segmentIsChinese: Bool {
        segment.text.contains { $0.isChineseCharacter }
    }

    private var isSaved: Bool {
        savedTermsStore.contains(chinese: chineseWord.isEmpty ? segment.text : chineseWord)
    }

    var body: some View {
        VStack(spacing: 16) {
            // Large character display - always show Chinese with pinyin
            VStack(spacing: 4) {
                if isLoadingTranslation {
                    ProgressView()
                        .controlSize(.small)
                    Text("Loading...")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                } else {
                    Text(pinyinText)
                        .font(.title3)
                        .foregroundStyle(.secondary)

                    Text(chineseWord)
                        .font(.system(size: 56, weight: .medium))

                    // Part of speech badge
                    Text(segment.partOfSpeech.displayName)
                        .font(.caption)
                        .fontWeight(.semibold)
                        .foregroundStyle(.white)
                        .padding(.horizontal, 10)
                        .padding(.vertical, 3)
                        .background(
                            Capsule()
                                .fill(segment.partOfSpeech.color)
                        )
                }
            }

            Divider()

            // Definition section - always shows English translation
            VStack(alignment: .leading, spacing: 8) {
                Text("Definition")
                    .font(.caption)
                    .fontWeight(.semibold)
                    .foregroundStyle(.secondary)

                if isLoadingTranslation {
                    HStack(spacing: 8) {
                        ProgressView()
                            .controlSize(.small)
                        Text("Translating...")
                            .font(.body)
                            .foregroundStyle(.secondary)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                } else if let error = translationError {
                    VStack(alignment: .leading, spacing: 4) {
                        Text(error)
                            .font(.caption)
                            .foregroundStyle(.red)

                        // Fallback to context if available
                        if !contextTranslation.isEmpty {
                            Text("Context: \(contextTranslation)")
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                } else {
                    Text(englishDefinition)
                        .font(.body)
                        .fontWeight(.medium)
                        .frame(maxWidth: .infinity, alignment: .leading)
                }
            }
            .padding(.horizontal)

            Divider()

            // Action buttons
            HStack(spacing: 16) {
                Button {
                    SpeechService.speakChinese(chineseWord)
                } label: {
                    Label("Speak", systemImage: "speaker.wave.2")
                }
                .buttonStyle(.bordered)
                .disabled(isLoadingTranslation || chineseWord.isEmpty)

                Button {
                    ClipboardService.copy(chineseWord)
                    showCopiedFeedback = true
                    onCopy()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                        showCopiedFeedback = false
                    }
                } label: {
                    Label(showCopiedFeedback ? "Copied!" : "Copy", systemImage: showCopiedFeedback ? "checkmark" : "doc.on.doc")
                }
                .buttonStyle(.bordered)
                .tint(showCopiedFeedback ? .green : nil)
                .disabled(isLoadingTranslation || chineseWord.isEmpty)

                Button {
                    // Pass the word-specific translation when saving
                    let definition = englishDefinition.isEmpty ? contextTranslation : englishDefinition
                    onSave(definition)
                } label: {
                    Label(isSaved ? "Saved" : "Save", systemImage: isSaved ? "bookmark.fill" : "bookmark")
                }
                .buttonStyle(.bordered)
                .tint(isSaved ? .green : nil)
                .disabled(isLoadingTranslation || isSaved)
            }

            // Copy with pinyin button
            Button {
                let definition = englishDefinition.isEmpty ? contextTranslation : englishDefinition
                let fullText = "\(chineseWord) (\(pinyinText))\n\(definition)"
                ClipboardService.copy(fullText)
                showCopiedFeedback = true
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                    showCopiedFeedback = false
                }
            } label: {
                Label("Copy with Pinyin", systemImage: "doc.on.doc.fill")
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .disabled(isLoadingTranslation)
        }
        .padding()
        .frame(minWidth: 280)
        .task {
            await fetchWordDetails()
        }
    }

    /// Fetch the translation details for this word
    /// Always produces: Chinese word, pinyin, and English definition
    private func fetchWordDetails() async {
        isLoadingTranslation = true
        translationError = nil

        do {
            if segmentIsChinese {
                // Input is Chinese: use as-is for Chinese, translate to English for definition
                chineseWord = segment.text
                pinyinText = segment.pinyin

                let translation = try await WordTranslationService.shared.translateToEnglish(segment.text)
                englishDefinition = translation
            } else {
                // Input is English: translate to Chinese, get pinyin, use original as definition
                englishDefinition = segment.text

                let chineseTranslation = try await WordTranslationService.shared.translateToChinese(segment.text)
                chineseWord = chineseTranslation
                pinyinText = PinyinConverter.convert(chineseTranslation)
            }

            await MainActor.run {
                isLoadingTranslation = false
            }
        } catch {
            await MainActor.run {
                // If translation fails, use what we have
                translationError = "Could not translate word"
                if segmentIsChinese {
                    chineseWord = segment.text
                    pinyinText = segment.pinyin
                    englishDefinition = contextTranslation
                } else {
                    englishDefinition = segment.text
                    chineseWord = contextTranslation.isEmpty ? segment.text : contextTranslation
                    pinyinText = PinyinConverter.convert(chineseWord)
                }
                isLoadingTranslation = false
            }
            print("Word translation error for '\(segment.text)': \(error)")
        }
    }
}

// MARK: - Preview

#Preview {
    VStack(spacing: 20) {
        RubyTextView(
            chineseText: "你好世界",
            englishMeaning: "Hello World"
        ) { segment in
            print("Tapped: \(segment.text)")
        }

        RubyTextView(
            chineseText: "我喜欢学习中文",
            englishMeaning: "I like to study Chinese"
        )
    }
    .padding()
    .environment(SavedTermsStore.shared)
}

//
//  EnglishRubyTextView.swift
//  SwiftMandarin
//
//  Word-by-word English text display with Chinese translations
//  Similar to RubyTextView but for English → Chinese
//

import SwiftUI

/// A single English word chip with translation
struct EnglishWordChip: View {
    let word: AnalyzedEnglishWord
    let showTranslation: Bool
    let onTap: () -> Void

    var body: some View {
        Button(action: onTap) {
            VStack(spacing: 2) {
                // English word
                Text(word.text)
                    .font(.title3)
                    .fontWeight(.medium)
                    .foregroundStyle(.primary)

                // Chinese translation (if available)
                if showTranslation, let translation = word.translation {
                    Text(translation)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }

                // Part of speech indicator
                Text(word.partOfSpeech.abbreviation)
                    .font(.caption2)
                    .foregroundStyle(word.partOfSpeech.color)
            }
            .padding(.horizontal, 8)
            .padding(.vertical, 4)
            .background(
                RoundedRectangle(cornerRadius: 8)
                    .fill(word.partOfSpeech.color.opacity(0.1))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .strokeBorder(word.partOfSpeech.color.opacity(0.3), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
    }
}

/// Word detail sheet for English words
struct EnglishWordDetailSheet: View {
    let word: AnalyzedEnglishWord
    @Environment(\.dismiss) private var dismiss
    @Environment(SavedTermsStore.self) private var savedTermsStore

    @State private var isLoading: Bool = false
    @State private var fullTranslation: String = ""

    private var isSaved: Bool {
        !chineseTranslation.isEmpty && savedTermsStore.contains(chinese: chineseTranslation)
    }

    /// Get the best available Chinese translation
    private var chineseTranslation: String {
        if !fullTranslation.isEmpty {
            return fullTranslation
        } else if let translation = word.translation, !translation.isEmpty {
            return translation
        }
        return ""
    }

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    // Word header with Chinese translation prominently displayed
                    VStack(spacing: 12) {
                        // English word
                        Text(word.text)
                            .font(.largeTitle)
                            .fontWeight(.bold)

                        // Chinese translation (large and prominent)
                        if isLoading {
                            HStack(spacing: 8) {
                                ProgressView()
                                    .controlSize(.small)
                                Text("正在翻译...")
                                    .font(.title2)
                                    .foregroundStyle(.secondary)
                            }
                        } else if !chineseTranslation.isEmpty {
                            Text(chineseTranslation)
                                .font(.system(size: 36, weight: .medium))
                                .foregroundStyle(.primary)
                        }

                        // Part of speech badge
                        HStack {
                            Text(word.partOfSpeech.englishName)
                                .font(.subheadline)
                                .foregroundStyle(.white)
                                .padding(.horizontal, 12)
                                .padding(.vertical, 4)
                                .background(
                                    Capsule()
                                        .fill(word.partOfSpeech.color)
                                )

                            Text(word.partOfSpeech.rawValue)
                                .font(.subheadline)
                                .foregroundStyle(.secondary)
                        }
                    }
                    .frame(maxWidth: .infinity)
                    .padding()
                    .background(
                        RoundedRectangle(cornerRadius: 16)
                            .fill(.ultraThinMaterial)
                    )

                    // Word forms section
                    VStack(alignment: .leading, spacing: 8) {
                        Text("词形变化")
                            .font(.headline)

                        HStack(spacing: 16) {
                            VStack(alignment: .leading) {
                                Text("原形")
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(word.lemma)
                                    .font(.body)
                                    .fontWeight(.medium)
                            }

                            if word.text.lowercased() != word.lemma.lowercased() {
                                VStack(alignment: .leading) {
                                    Text("当前形式")
                                        .font(.caption)
                                        .foregroundStyle(.secondary)
                                    Text(word.text)
                                        .font(.body)
                                        .fontWeight(.medium)
                                }
                            }
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding()
                    .background(
                        RoundedRectangle(cornerRadius: 12)
                            .fill(.ultraThinMaterial)
                    )

                    // Part of speech info
                    VStack(alignment: .leading, spacing: 8) {
                        Text("词性说明")
                            .font(.headline)

                        Text("\(word.partOfSpeech.englishName) (\(word.partOfSpeech.rawValue))")
                            .font(.body)

                        if !word.partOfSpeech.examples.isEmpty {
                            Text("同类词例: \(word.partOfSpeech.examples.prefix(5).joined(separator: ", "))")
                                .font(.subheadline)
                                .foregroundStyle(.secondary)
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding()
                    .background(
                        RoundedRectangle(cornerRadius: 12)
                            .fill(.ultraThinMaterial)
                    )

                    // Action buttons
                    HStack(spacing: 12) {
                        Button {
                            SpeechService.speakEnglish(word.text)
                        } label: {
                            Label("朗读", systemImage: "speaker.wave.2")
                                .frame(maxWidth: .infinity)
                        }
                        .buttonStyle(.bordered)

                        Button {
                            saveToVocabulary()
                        } label: {
                            Label(isSaved ? "已保存" : "保存到词汇本", systemImage: isSaved ? "bookmark.fill" : "bookmark")
                                .frame(maxWidth: .infinity)
                        }
                        .buttonStyle(.borderedProminent)
                        .disabled(isSaved || chineseTranslation.isEmpty)
                    }
                }
                .padding()
            }
            .navigationTitle("单词详情")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("完成") {
                        dismiss()
                    }
                }
            }
            .task {
                // Auto-translate when sheet appears if no translation available
                if chineseTranslation.isEmpty {
                    await translateWord()
                }
            }
        }
    }

    private func translateWord() async {
        isLoading = true
        defer { isLoading = false }

        do {
            // Translate English word to Chinese
            let translation = try await WordTranslationService.shared.translateToChinese(word.lemma)
            fullTranslation = translation
        } catch {
            // Handle error silently for now
            fullTranslation = word.translation ?? ""
        }
    }

    private func saveToVocabulary() {
        // Save with Chinese translation as the main term, English word as definition
        let term = SavedTerm(
            chinese: chineseTranslation,
            pinyin: PinyinConverter.convert(chineseTranslation),
            definition: word.lemma.caseInsensitiveCompare(word.text) == .orderedSame ? word.text : "\(word.text) (\(word.lemma))",
            partOfSpeech: word.partOfSpeech.rawValue
        )
        savedTermsStore.add(term)
    }
}

/// Inline punctuation display for English text (no chip styling)
struct EnglishPunctuationView: View {
    let text: String

    var body: some View {
        Text(text)
            .font(.title3)
            .fontWeight(.medium)
            .foregroundStyle(.primary)
    }
}

/// Ruby-style text view for English with word-by-word translations
struct EnglishRubyTextView: View {
    let words: [AnalyzedEnglishWord]
    let showTranslations: Bool
    let onWordTap: (AnalyzedEnglishWord) -> Void

    init(words: [AnalyzedEnglishWord], showTranslations: Bool = true, onWordTap: @escaping (AnalyzedEnglishWord) -> Void) {
        self.words = words
        self.showTranslations = showTranslations
        self.onWordTap = onWordTap
    }

    var body: some View {
        FlowLayout(spacing: 8) {
            ForEach(words) { word in
                if word.isPunctuation {
                    // Display punctuation inline without chip styling
                    EnglishPunctuationView(text: word.text)
                } else {
                    EnglishWordChip(
                        word: word,
                        showTranslation: showTranslations,
                        onTap: { onWordTap(word) }
                    )
                }
            }
        }
    }
}

