import SwiftUI
import AppIntents

@main
struct SwiftMandarinApp: App {
    // Shared stores for app-wide state using @Observable
    @State private var savedTermsStore = SavedTermsStore.shared
    @State private var historyStore = TranslationHistoryStore.shared
    @State private var learningStore = LearningProgressStore.shared
    @State private var activityStore = LearningActivityStore.shared
    @State private var routeStore = AppRouteStore.shared

    init() {
        // Ensures app shortcuts are registered and entity-backed parameters are refreshed.
        SwiftMandarinShortcutsProvider.updateAppShortcutParameters()
    }

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environment(savedTermsStore)
                .environment(historyStore)
                .environment(learningStore)
                .environment(activityStore)
                .environment(routeStore)
        }

        #if os(macOS)
        Settings {
            MacOSSettingsView()
                .environment(savedTermsStore)
                .environment(historyStore)
                .environment(learningStore)
                .environment(activityStore)
                .environment(routeStore)
        }
        #endif
    }
}

//
//  ContentView.swift
//  SwiftMandarin
//
//  Created by Roger Lin on 2/11/26.
//

import SwiftUI
import AppIntents

/// Main navigation container using TabView with sidebarAdaptable style
/// - iOS: Bottom tab bar (5 tabs)
/// - iPadOS: Floating tab bar that morphs to sidebar
/// - macOS: NavigationSplitView with sidebar
struct ContentView: View {
    @Environment(AppRouteStore.self) private var routeStore
    @Environment(\.scenePhase) private var scenePhase

    private var selectedTabBinding: Binding<AppTab> {
        Binding(
            get: { routeStore.selectedTab },
            set: { routeStore.selectedTab = $0 }
        )
    }

    var body: some View {
        contentView
            .onAppear {
                SwiftMandarinShortcutsProvider.updateAppShortcutParameters()
            }
            .onChange(of: scenePhase) { _, newPhase in
                if newPhase == .active {
                    SwiftMandarinShortcutsProvider.updateAppShortcutParameters()
                }
            }
    }

    @ViewBuilder
    private var contentView: some View {
        #if os(macOS)
        MacOSContentView(selectedTab: selectedTabBinding)
        #else
        iOSContentView(selectedTab: selectedTabBinding)
        #endif
    }
}

// MARK: - App Tabs

enum AppTab: String, CaseIterable, Identifiable {
    case translate
    case photo
    case history
    case vocabulary
    case learn
    case phrases
    case stats
    case more

    var id: String { rawValue }

    var title: String {
        switch self {
        case .translate: return "Translate"
        case .photo: return "Photo"
        case .history: return "History"
        case .vocabulary: return "Vocabulary"
        case .learn: return "Learn"
        case .phrases: return "Phrases"
        case .stats: return "Stats"
        case .more: return "More"
        }
    }

    var icon: String {
        switch self {
        case .translate: return "character.bubble"
        case .photo: return "camera.viewfinder"
        case .history: return "clock"
        case .vocabulary: return "text.book.closed"
        case .learn: return "brain.head.profile"
        case .phrases: return "quote.bubble"
        case .stats: return "chart.bar.fill"
        case .more: return "ellipsis.circle"
        }
    }
}

// MARK: - iOS/iPadOS Navigation

struct iOSContentView: View {
    @Binding var selectedTab: AppTab

    var body: some View {
        TabView(selection: $selectedTab) {
            Tab(AppTab.translate.title, systemImage: AppTab.translate.icon, value: .translate) {
                TranslateView()
            }

            Tab(AppTab.photo.title, systemImage: AppTab.photo.icon, value: .photo) {
                PhotoTranslateView()
            }

            Tab(AppTab.history.title, systemImage: AppTab.history.icon, value: .history) {
                HistoryTabView(selectedTab: $selectedTab)
            }

            Tab(AppTab.vocabulary.title, systemImage: AppTab.vocabulary.icon, value: .vocabulary) {
                VocabularyView()
            }

            Tab(AppTab.learn.title, systemImage: AppTab.learn.icon, value: .learn) {
                LearnView()
            }

            Tab(AppTab.phrases.title, systemImage: AppTab.phrases.icon, value: .phrases) {
                PhrasesView()
            }

            Tab(AppTab.stats.title, systemImage: AppTab.stats.icon, value: .stats) {
                StatsView()
            }

